// lib/viewmodels/table_export_viewmodel.dart
//
// Export any table to Excel or PDF (spec
// docs/superpowers/specs/2026-11-28-table-export-design.md). A screen hands
// over the rows it shows (after its own search, filters and sort); the footer
// ("Generated by ... on ...") comes from the signed-in user and the clock,
// never from the screen. Both builds.
import '../core/console/logger.dart';
import '../core/models/export_table.dart';
import '../core/models/user_role.dart';
import '../core/services/table_export_xlsx.dart';
import '../core/services/table_reader.dart' show csvGrid;
import 'auth_viewmodel.dart';
import 'viewmodel_exception.dart';

class TableExportViewModel {
  final AuthViewModel _auth;
  final ScopedLogger _log;

  TableExportViewModel({required AuthViewModel auth, Logger? logger})
      : _auth = auth,
        _log = ScopedLogger(logger, 'TableExportViewModel');

  void _requireSignIn() {
    final error = _auth.requireActiveSession();
    if (error != null) throw ViewModelException(error);
  }

  /// The table as an .xlsx file's bytes.
  Future<List<int>> xlsx(ExportTable t, {DateTime? now}) async {
    _requireSignIn();
    _log('xlsx("${t.title}", ${t.rows.length} rows)');
    try {
      return buildTableXlsx(t, footer: footer(now: now));
    } on ExportTableException catch (e) {
      throw ViewModelException(e.message);
    }
  }

  /// A CSV (as BASA's CSV exports write it) as a table: the first non-empty
  /// row is the columns, empty rows are skipped. A column is a number column
  /// only when every value is a plain number (no leading zero, at most 10
  /// characters), so an LRN stays text.
  ExportTable tableFromCsv(String csvText, String title,
      {String? school, String? schoolYear, List<String> filters = const []}) {
    _requireSignIn();
    _log('tableFromCsv("$title")');
    final grid = csvGrid(csvText).where((r) => r.any((c) => c.trim().isNotEmpty)).toList();
    if (grid.isEmpty) throw const ViewModelException('The file is empty.');
    final header = grid.first.map((h) => h.trim()).toList();
    final body = [
      for (final r in grid.skip(1)) [for (var c = 0; c < header.length; c++) c < r.length ? r[c].trim() : ''],
    ];
    final number = [
      for (var c = 0; c < header.length; c++)
        body.every((r) => r[c].isEmpty || _plainNumber.hasMatch(r[c])) && body.any((r) => r[c].isNotEmpty),
    ];
    return ExportTable(title,
        school: school,
        schoolYear: schoolYear,
        filters: filters,
        columns: [
          for (var c = 0; c < header.length; c++)
            ExportColumn(header[c], kind: number[c] ? ExportColumnKind.number : ExportColumnKind.text),
        ],
        rows: [
          for (final r in body)
            [for (var c = 0; c < header.length; c++) r[c].isEmpty ? null : (number[c] ? num.parse(r[c]) : r[c])],
        ]);
  }

  /// -3, 0, 0.5, 2.5, 12345: no leading zero (an LRN or code keeps it), at
  /// most 10 characters.
  static final _plainNumber = RegExp(r'^(?=.{1,10}$)-?(0|[1-9]\d*)(\.\d+)?$');

  /// "Generated by Maria Santos (Coordinator) on 28 Nov 2026, 9:14 AM"
  /// (device time).
  String footer({DateTime? now}) {
    _requireSignIn();
    final me = _auth.currentUser!;
    final role = switch (me.role) {
      UserRole.admin => me.schoolId == null ? 'Admin, region' : 'Admin',
      UserRole.coordinator => 'Coordinator',
      UserRole.tutor => 'Tutor',
    };
    return 'Generated by ${me.fullName} ($role) on ${_when(now ?? DateTime.now())}';
  }

  /// "<title> 2026-11-28.<extension>", with the characters a file name can't
  /// hold replaced by "-".
  String fileName(ExportTable t, String extension, {DateTime? now}) {
    final d = now ?? DateTime.now();
    final day = '${d.year}-${_two(d.month)}-${_two(d.day)}';
    final name = t.title.replaceAll(RegExp(r'[\\/:*?"<>|]'), '-').trim();
    return '${name.isEmpty ? 'Export' : name} $day.$extension';
  }

  static const _months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  static String _when(DateTime d) {
    final hour = d.hour % 12 == 0 ? 12 : d.hour % 12;
    return '${d.day} ${_months[d.month - 1]} ${d.year}, $hour:${_two(d.minute)} ${d.hour < 12 ? 'AM' : 'PM'}';
  }

  static String _two(int n) => n.toString().padLeft(2, '0');
}
